CREATE OR REPLACE FUNCTION public.rpc_aprovar_os_v1(p_os_id uuid, p_origem text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_origin text; v_status text; v_org uuid;
BEGIN
 -- Normalização não consulta dados. Alias inválido/inexistente negado igualmente.
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin='b2b' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(p_os_id,v_origin);
 IF v_origin='manual' THEN SELECT status::text INTO v_status FROM public.ordens_servico WHERE id=p_os_id;
 ELSE SELECT status::text INTO v_status FROM public.ordens_servico_onfarm WHERE id=p_os_id; END IF;
 IF v_status='aprovada' THEN RETURN jsonb_build_object('success',true,'replay',true,'status','aprovada'); END IF;
 IF v_status IS DISTINCT FROM 'aberta' THEN RETURN jsonb_build_object('success',false,'message','Somente OS aberta pode ser aprovada separadamente.'); END IF;
 IF v_origin='manual' THEN UPDATE public.ordens_servico SET status='aprovada' WHERE id=p_os_id;
 ELSE UPDATE public.ordens_servico_onfarm SET status='aprovada' WHERE id=p_os_id; END IF;
 PERFORM private.assert_os_approval_scope(p_os_id,v_origin);
 RETURN jsonb_build_object('success',true,'replay',false,'status','aprovada','message','OS aprovada; programação e fabricação não iniciadas.');
END $function$

CREATE OR REPLACE FUNCTION public.fn_create_programacao_on_os_classica_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text NOT IN ('aberta','aprovada','programada') THEN
    RETURN NEW;
  END IF;
  IF NEW.produto_id IS NULL AND NEW.microrganismo_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.programacao_producao WHERE ordem_servico_id = NEW.id) THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.programacao_producao
    (produto_id, microrganismo_id, volume_necessario, data_programada, status, ordem_servico_id)
  VALUES
    (NEW.produto_id, NEW.microrganismo_id, NEW.volume_total_ml,
     COALESCE(NEW.data_programada, CURRENT_DATE), 'aguardando', NEW.id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_cancelar_v1(p_entrega_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_entrega public.entregas%ROWTYPE;
  v_item public.estoque_produto%ROWTYPE;
  v_mov public.estoque_movimentacoes%ROWTYPE;
  v_origem text;
  v_estorno jsonb;
  v_reserva jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ENTREGA_NAO_AUTENTICADO' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (
    public.has_role(v_uid, 'administrador'::public.app_role)
    OR public.has_role(v_uid, 'gestor'::public.app_role)
    OR public.has_role(v_uid, 'administrativo'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_SEM_PERMISSAO' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_entrega_id IS NULL OR v_motivo IS NULL THEN
    RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_PARAMETROS_INVALIDOS' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('entrega_cancelar:' || p_entrega_id::text));
  SELECT * INTO v_entrega FROM public.entregas WHERE id = p_entrega_id FOR UPDATE;

  IF v_entrega.id IS NULL THEN
    RAISE EXCEPTION 'ENTREGA_NAO_ENCONTRADA' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_entrega.status::text = 'cancelada' THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_entrega.id, 'message', 'Entrega ja estava cancelada.');
  END IF;
  IF v_entrega.status::text = 'entregue' THEN
    RAISE EXCEPTION 'ENTREGA_CONFIRMADA_EXIGE_DEVOLUCAO' USING ERRCODE = 'check_violation';
  END IF;
  IF v_entrega.status::text NOT IN ('separado', 'em_rota') THEN
    RAISE EXCEPTION 'ENTREGA_STATUS_NAO_CANCELAVEL' USING ERRCODE = 'check_violation';
  END IF;

  v_origem := CASE WHEN v_entrega.ordem_servico_onfarm_id IS NOT NULL THEN 'onfarm' ELSE 'manual' END;

  IF v_entrega.estoque_produto_id IS NOT NULL THEN
    SELECT * INTO v_item FROM public.estoque_produto WHERE id = v_entrega.estoque_produto_id FOR UPDATE;
    IF v_item.id IS NULL THEN
      RAISE EXCEPTION 'ENTREGA_ESTOQUE_NAO_ENCONTRADO' USING ERRCODE = 'no_data_found';
    END IF;

    SELECT m.* INTO v_mov
      FROM public.estoque_movimentacoes m
     WHERE m.estoque_produto_id = v_item.id
       AND m.referencia_tipo = 'entrega'
       AND m.referencia_id = v_entrega.id
       AND m.acao IN ('expedicao', 'entrega')
       AND NOT EXISTS (SELECT 1 FROM public.estoque_movimentacoes r WHERE r.movimentacao_origem_id = m.id)
     ORDER BY m.created_at DESC, m.id DESC
     LIMIT 1
     FOR UPDATE;

    IF v_mov.id IS NOT NULL THEN
      v_estorno := public.rpc_estoque_operar_v1(
        'estorno_expedicao', v_item.id, NULL,
        'entrega-cancel-estorno:' || v_entrega.id::text,
        jsonb_build_object(
          'origem', 'rpc_entrega_cancelar_v1', 'referencia_tipo', 'entrega',
          'referencia_id', v_entrega.id, 'movimentacao_origem_id', v_mov.id, 'motivo', v_motivo
        )
      );
      SELECT * INTO v_item FROM public.estoque_produto WHERE id = v_entrega.estoque_produto_id FOR UPDATE;
    END IF;

    IF v_item.status::text = 'reservado' THEN
      v_reserva := public.rpc_cockpit_cancelar_reserva_v1(
        v_item.id,
        COALESCE(v_entrega.ordem_servico_onfarm_id, v_entrega.ordem_servico_id),
        v_origem,
        'Cancelamento da entrega ' || v_entrega.id::text || ': ' || v_motivo
      );
    ELSIF v_item.status::text NOT IN ('disponivel', 'estornado') THEN
      RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_ESTOQUE_INCONSISTENTE: status %', v_item.status USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  PERFORM set_config('app.entrega_cancelamento_id', v_entrega.id::text, true);
  UPDATE public.entregas
     SET status = 'cancelada'::public.status_entrega, motivo_cancelamento = v_motivo
   WHERE id = v_entrega.id;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (
    COALESCE(v_entrega.ordem_servico_onfarm_id, v_entrega.ordem_servico_id),
    v_origem, v_entrega.lote_id, 'entrega_criada', 'entrega_cancelada',
    'cancelar_entrega_v1', v_uid, 'Cancelamento atomico. Motivo: ' || v_motivo
  );

  RETURN jsonb_build_object(
    'success', true, 'replay', false, 'entrega_id', v_entrega.id,
    'estoque_estornado', v_estorno IS NOT NULL,
    'reserva_liberada', v_reserva IS NOT NULL,
    'message', 'Entrega cancelada e estoque recomposto.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_envase_avanca_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Ensure lote is marked as aprovado (envase only passes if CQ aprovado)
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id AND status::text <> 'aprovado';
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id AND status::text <> 'aprovado';

  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'pronto_entrega'
      WHERE id = v_os_onfarm_id
        AND status::text = 'envase';
  END IF;

  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'pronto_entrega'
      WHERE id = v_os_id
        AND status::text = 'envase';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_confirmar_engine_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb DEFAULT '{}'::jsonb, p_opcoes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_os_id uuid;
  v_ent record;
  v_est public.estoque_produto%ROWTYPE;
  v_pendentes int; v_total_entregue numeric; v_total_reservado numeric;
  v_finalizada boolean := false; v_avanco jsonb;
  v_recebedor_nome text;
  v_entregue_em timestamptz;
  v_faturamento text := nullif(btrim(coalesce(p_opcoes->>'faturamento','')), '');
  v_motivo_nb text := nullif(btrim(coalesce(p_opcoes->>'motivo_nao_faturavel','')), '');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;
  IF p_entrega_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS'; END IF;

  PERFORM public.fn_estoque_ctx_open(jsonb_build_object(
    'acao','entrega','origem','fn_entrega_confirmar_engine_v1','usuario_id', v_uid::text));

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_entrega:' || p_entrega_id::text));

  SELECT e.id, e.status::text AS status, e.estoque_produto_id,
         coalesce(e.quantidade_entregue, 0) AS qtd, e.partner_order_id,
         e.ordem_servico_id, e.ordem_servico_onfarm_id
    INTO v_ent
    FROM public.entregas e
   WHERE e.id = p_entrega_id
   FOR UPDATE;

  IF v_ent.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_NAO_ENCONTRADA'; END IF;

  -- Origem: explícita quando informada; derivada do vínculo caso contrário.
  IF nullif(btrim(coalesce(p_origem,'')), '') IS NOT NULL THEN
    v_origem := public.fn_cockpit_norm_origem(p_origem);
  ELSIF v_ent.ordem_servico_onfarm_id IS NOT NULL THEN
    v_origem := 'onfarm';
  ELSIF v_ent.partner_order_id IS NOT NULL THEN
    v_origem := 'b2b';
  ELSE
    v_origem := 'manual';
  END IF;

  v_origem := public.fn_entrega_assert_confirmador(v_origem);

  v_os_id := CASE WHEN v_origem = 'onfarm' THEN v_ent.ordem_servico_onfarm_id
                  ELSE v_ent.ordem_servico_id END;

  IF p_os_id IS NOT NULL AND v_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_OS';
  END IF;

  IF v_ent.status = 'cancelada' THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_CANCELADA'; END IF;
  IF v_ent.status = 'entregue' THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'finalizada', false,
      'entrega_id', p_entrega_id,
      'message', 'Entrega já confirmada anteriormente.');
  END IF;

  IF v_origem = 'b2b' AND v_ent.partner_order_id IS NOT NULL THEN
    PERFORM public.fn_cockpit_assert_b2b_liberado(v_ent.partner_order_id);
  END IF;

  IF v_ent.estoque_produto_id IS NOT NULL THEN
    SELECT * INTO v_est FROM public.estoque_produto WHERE id = v_ent.estoque_produto_id FOR UPDATE;
    IF v_est.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO'; END IF;
    IF v_est.status::text <> 'expedido' THEN
      IF v_os_id IS NOT NULL THEN
        IF v_est.reservado_para_os_id IS DISTINCT FROM v_os_id THEN
          RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
        END IF;
        IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
          RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
        END IF;
      END IF;
      IF v_ent.qtd > coalesce(v_est.quantidade, 0) THEN
        RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
      END IF;
    END IF;
  END IF;

  -- Recebedor físico é OBRIGATÓRIO e distinto de confirmado_por.
  v_recebedor_nome := nullif(btrim(coalesce(p_recebedor->>'nome','')), '');
  IF v_recebedor_nome IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_RECEBEDOR_OBRIGATORIO';
  END IF;

  v_entregue_em := coalesce(nullif(btrim(coalesce(p_opcoes->>'entregue_em','')), '')::timestamptz, now());

  UPDATE public.entregas
     SET status = 'entregue'::public.status_entrega,
         entregue_em = v_entregue_em,
         recebido_por_nome = v_recebedor_nome,
         recebido_por_cargo = coalesce(nullif(btrim(coalesce(p_recebedor->>'cargo','')), ''), recebido_por_cargo),
         recebido_por_documento = coalesce(nullif(btrim(coalesce(p_recebedor->>'documento','')), ''), recebido_por_documento),
         observacoes_confirmacao = coalesce(nullif(btrim(coalesce(p_recebedor->>'observacoes','')), ''), observacoes_confirmacao),
         confirmado_por = v_uid,
         financial_status = CASE WHEN v_faturamento = 'bill_later' THEN 'PENDING_BILLING'
                                 ELSE financial_status END
   WHERE id = p_entrega_id;

  IF v_est.id IS NOT NULL THEN
    UPDATE public.estoque_produto
       SET status = 'expedido'::public.status_estoque, expedido_por = v_uid,
           expedido_em = now(), updated_at = now()
     WHERE id = v_est.id AND status <> 'expedido'::public.status_estoque;

    IF FOUND THEN
      INSERT INTO public.estoque_movimentacoes
        (estoque_produto_id, acao, quantidade, status_anterior, status_novo, os_id, os_tipo, usuario_id, lote_id, observacao)
      VALUES (v_est.id, 'expedicao', v_ent.qtd, 'reservado', 'expedido',
              v_os_id, v_origem, v_uid, v_est.lote_id, 'Baixa por confirmação de entrega');
    END IF;
  END IF;

  IF v_os_id IS NOT NULL THEN
    v_avanco := public._rpc_avancar_esteira_laboratorio_internal(v_os_id, v_origem, 'enviar_entrega', NULL);

    INSERT INTO public.laboratorio_esteira_eventos
      (os_id, origem_os, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
    VALUES (v_os_id, v_origem, 'em_entrega', 'entregue', 'confirmar_entrega_v1', v_uid,
            format('Confirmação transacional da entrega %s (recebedor: %s)', p_entrega_id, v_recebedor_nome));

    IF v_origem = 'onfarm' THEN
      SELECT count(*) FILTER (WHERE status::text NOT IN ('entregue','cancelada')),
             coalesce(sum(quantidade_entregue) FILTER (WHERE status::text = 'entregue'), 0)
        INTO v_pendentes, v_total_entregue
        FROM public.entregas WHERE ordem_servico_onfarm_id = v_os_id;
    ELSE
      SELECT count(*) FILTER (WHERE status::text NOT IN ('entregue','cancelada')),
             coalesce(sum(quantidade_entregue) FILTER (WHERE status::text = 'entregue'), 0)
        INTO v_pendentes, v_total_entregue
        FROM public.entregas WHERE ordem_servico_id = v_os_id;
    END IF;

    SELECT coalesce(sum(quantidade_reservada), 0) INTO v_total_reservado
      FROM public.estoque_produto
     WHERE reservado_para_os_id = v_os_id
       AND coalesce(reservado_para_os_tipo, v_origem) = v_origem
       AND status <> 'estornado'::public.status_estoque;

    IF v_pendentes = 0 AND v_total_reservado > 0 AND v_total_entregue >= v_total_reservado THEN
      v_avanco := public._rpc_avancar_esteira_laboratorio_internal(v_os_id, v_origem, 'finalizar_os', NULL);
      IF coalesce((v_avanco->>'success')::boolean, false) THEN
        v_finalizada := true;
        INSERT INTO public.laboratorio_esteira_eventos
          (os_id, origem_os, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
        VALUES (v_os_id, v_origem, 'entregue', 'finalizada', 'finalizacao_automatica_por_entrega', v_uid,
                'Cobertura completa: OS finalizada na mesma transação da confirmação de entrega.');
      END IF;
    END IF;
  END IF;

  IF v_faturamento = 'not_billable' THEN
    IF v_motivo_nb IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_MOTIVO_NAO_FATURAVEL_OBRIGATORIO'; END IF;
    PERFORM public.fn_mark_entrega_not_billable(p_entrega_id, v_motivo_nb);
  END IF;

  RETURN jsonb_build_object('success', true, 'replay', false, 'finalizada', v_finalizada,
    'entrega_id', p_entrega_id, 'os_id', v_os_id, 'origem', v_origem,
    'parcial', (coalesce(v_pendentes, 0) > 0 OR coalesce(v_total_entregue, 0) < coalesce(v_total_reservado, 0)),
    'total_entregue', coalesce(v_total_entregue, 0), 'total_reservado', coalesce(v_total_reservado, 0),
    'message', CASE WHEN v_finalizada THEN 'Entrega confirmada — OS finalizada.'
                    ELSE 'Entrega confirmada.' END);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_mark_entrega_not_billable(_entrega_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
BEGIN
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para marcar entrega como sem cobrança.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) = 0 THEN
    RAISE EXCEPTION 'Motivo é obrigatório.' USING ERRCODE='check_violation';
  END IF;

  SELECT * INTO v_entrega FROM public.entregas WHERE id = _entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.'; END IF;
  IF v_entrega.receivable_id IS NOT NULL THEN
    RAISE EXCEPTION 'Entrega já foi faturada.' USING ERRCODE='check_violation';
  END IF;

  UPDATE public.entregas
    SET financial_status = 'NOT_BILLABLE',
        not_billable_reason = _reason
    WHERE id = _entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES ('entregas', _entrega_id, 'MARK_NOT_BILLABLE',
    jsonb_build_object('financial_status', v_entrega.financial_status),
    jsonb_build_object('financial_status', 'NOT_BILLABLE', 'reason', _reason),
    v_uid);
END $function$

CREATE OR REPLACE FUNCTION public.generate_production_orders_from_partner(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_planning_id uuid;
  v_partner_id uuid;
  v_order_numero text;
  v_order_status text;
  v_ready boolean;
  v_partner_nome text;
  v_grp RECORD;
  v_item RECORD;
  v_os_id uuid;
  v_numero text;
  v_count int := 0;
  v_nonlab_count int := 0;
  v_uid uuid := auth.uid();
  v_ids uuid[] := ARRAY[]::uuid[];
  v_anchor_item_id uuid;
BEGIN
 IF NOT platform_private.lab_partner_order_authorized(p_partner_order_id) THEN
  RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;

  -- H5-B01: serializa geração concorrente por pedido (idempotência de resultado)
  PERFORM pg_advisory_xact_lock(hashtext('generate_production_orders_from_partner:' || p_partner_order_id::text));

  SELECT po.partner_id, po.numero, po.status::text, po.ready_for_production
    INTO v_partner_id, v_order_numero, v_order_status, v_ready
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'Pedido B2B não encontrado';
  END IF;

  IF v_order_status IN ('cancelado','reprovado','faturado','entregue') THEN
    RAISE EXCEPTION 'Pedido B2B não pode gerar produção (status: %)', v_order_status;
  END IF;

  -- Fase 7: bloqueia produção enquanto aprovação financeira exigida está pendente/rejeitada
   IF EXISTS (
     SELECT 1 FROM public.partner_orders po2
     WHERE po2.id = p_partner_order_id
       AND po2.requires_financial_approval = true
       AND po2.financial_approval_status IN ('pending','rejected')
   ) THEN
     RAISE EXCEPTION 'financial_approval_required_before_production';
   END IF;

   IF v_order_status <> 'aprovado' OR v_ready IS NOT TRUE THEN
    RAISE EXCEPTION 'Pedido B2B ainda não está aprovado para produção.';
  END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = p_partner_order_id;
  IF v_planning_id IS NULL THEN
    RAISE EXCEPTION 'Planejamento não encontrado para o pedido %', p_partner_order_id;
  END IF;

  SELECT COALESCE(nome_fantasia, razao_social) INTO v_partner_nome FROM public.partner_accounts WHERE id = v_partner_id;

  SELECT count(*) INTO v_nonlab_count FROM public.partner_order_items poi
   WHERE poi.order_id=p_partner_order_id
     AND NOT platform_private.lab_item_is_manufacturable(poi.product_id,poi.microrganismo_id);

  FOR v_grp IN
    WITH itens AS (
      SELECT poi.id,
             poi.product_id,
             poi.quantidade,
             COALESCE(poi.unidade_medida,'unidade') AS unidade_medida,
             poi.preco_tabela_snapshot,
             poi.preco_unitario,
             poi.produto_nome_snapshot,
             poi.produto_codigo_snapshot,
             poi.created_at,
             cv.volume_ml AS vasilhame_volume_ml
      FROM public.partner_order_items poi
      LEFT JOIN LATERAL (
        SELECT cv2.volume_ml
          FROM public.catalogo_volumes cv2
         WHERE cv2.item_tipo = 'produto'
           AND cv2.produto_id = poi.product_id
           AND cv2.ativo = true
         ORDER BY (cv2.preco_brl = COALESCE(poi.preco_tabela_snapshot, poi.preco_unitario)) DESC,
                  ABS(cv2.preco_brl - COALESCE(poi.preco_tabela_snapshot, poi.preco_unitario)) ASC
         LIMIT 1
      ) cv ON true
      WHERE poi.order_id = p_partner_order_id
        AND poi.product_id IS NOT NULL
        AND platform_private.lab_item_is_manufacturable(poi.product_id,poi.microrganismo_id)
        AND COALESCE(poi.unidade_medida,'unidade') <> 'hectare'
        AND NOT EXISTS (
          SELECT 1 FROM public.production_order_link l WHERE l.partner_order_item_id = poi.id
        )
    )
    SELECT product_id,
           MIN(produto_nome_snapshot) AS produto_nome,
           MIN(produto_codigo_snapshot) AS produto_codigo,
           SUM(
             CASE unidade_medida
               WHEN 'ml'    THEN quantidade
               WHEN 'litro' THEN quantidade * 1000
               WHEN 'unidade' THEN quantidade * vasilhame_volume_ml
               WHEN 'dose'    THEN quantidade * vasilhame_volume_ml
               ELSE NULL
             END
           ) AS volume_total_ml,
           bool_or(
             unidade_medida IN ('unidade','dose') AND vasilhame_volume_ml IS NULL
           ) AS faltou_vasilhame,
           array_agg(id ORDER BY created_at, id) AS item_ids,
           (array_agg(id ORDER BY created_at, id))[1] AS anchor_id
    FROM itens
    GROUP BY product_id
  LOOP
    IF v_grp.faltou_vasilhame THEN
      RAISE EXCEPTION 'Produto % (%) está em unidade/dose mas não tem vasilhame ativo no catálogo. Configure o vasilhame antes de gerar produção.',
        COALESCE(v_grp.produto_nome,'?'), COALESCE(v_grp.produto_codigo,'?');
    END IF;

    IF v_grp.volume_total_ml IS NULL OR v_grp.volume_total_ml <= 0 THEN
      RAISE EXCEPTION 'Não foi possível calcular o volume do produto % (%).',
        COALESCE(v_grp.produto_nome,'?'), COALESCE(v_grp.produto_codigo,'?');
    END IF;

    v_anchor_item_id := v_grp.anchor_id;
    v_numero := 'OS-B2B-' || to_char(now(),'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,6);

    INSERT INTO public.ordens_servico (
      cliente_id, fazenda_id, talhao_id, produto_id, volume_total_ml, area_hectares,
      prioridade, status, tipo_item, numero_os,
      partner_order_id, partner_order_item_id, origem
    ) VALUES (
      NULL, NULL, NULL, v_grp.product_id, v_grp.volume_total_ml, NULL,
      'media','aberta','produto', v_numero,
      p_partner_order_id, v_anchor_item_id, 'b2b'
    ) RETURNING id INTO v_os_id;

    INSERT INTO public.production_order_link (
      partner_order_id, partner_order_item_id, planning_id, ordem_servico_id, created_by
    )
    SELECT p_partner_order_id, unnest(v_grp.item_ids), v_planning_id, v_os_id, v_uid;

    v_ids := array_append(v_ids, v_os_id);
    v_count := v_count + 1;
  END LOOP;

  FOR v_item IN
    SELECT poi.* FROM public.partner_order_items poi
    WHERE poi.order_id = p_partner_order_id
      AND platform_private.lab_item_is_manufacturable(poi.product_id,poi.microrganismo_id)
      AND NOT EXISTS (SELECT 1 FROM public.production_order_link l WHERE l.partner_order_item_id = poi.id)
      AND (
        poi.product_id IS NULL
        OR COALESCE(poi.unidade_medida,'unidade') = 'hectare'
      )
  LOOP
    v_numero := 'OS-B2B-' || to_char(now(),'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,6);

    INSERT INTO public.ordens_servico (
      cliente_id, fazenda_id, talhao_id, produto_id, microrganismo_id, volume_total_ml, area_hectares,
      prioridade, status, tipo_item, numero_os,
      partner_order_id, partner_order_item_id, origem
    ) VALUES (
      NULL, NULL, NULL, v_item.product_id, v_item.microrganismo_id, NULL,
      CASE WHEN COALESCE(v_item.unidade_medida,'unidade') = 'hectare' THEN v_item.quantidade ELSE NULL END,
      'media','aberta',
      CASE WHEN v_item.product_id IS NULL THEN 'microrganismo' ELSE 'produto' END,
      v_numero,
      p_partner_order_id, v_item.id, 'b2b'
    ) RETURNING id INTO v_os_id;

    INSERT INTO public.production_order_link (
      partner_order_id, partner_order_item_id, planning_id, ordem_servico_id, created_by
    ) VALUES (p_partner_order_id, v_item.id, v_planning_id, v_os_id, v_uid);

    v_ids := array_append(v_ids, v_os_id);
    v_count := v_count + 1;
  END LOOP;

  IF v_count = 0 THEN
    RETURN jsonb_build_object('ok', true, 'os_created', 0, 'planning_id', v_planning_id,
                              'non_lab_items',v_nonlab_count, 'message', 'Nenhuma nova OS biológica gerada; itens não laboratoriais permanecem no pedido.');
  END IF;

  UPDATE public.production_planning
     SET status = 'planejado', updated_at = now()
   WHERE id = v_planning_id AND status = 'aguardando_planejamento';

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (p_partner_order_id, 'op_gerada', v_uid, jsonb_build_object('os_count', v_count, 'planning_id', v_planning_id));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (
    p_partner_order_id, v_partner_id, v_uid, 'op_gerada',
    jsonb_build_object(
      'planning_id', v_planning_id,
      'os_count', v_count,
      'ordens_servico_ids', to_jsonb(v_ids),
      'created_at', now()
    )
  );

  RETURN jsonb_build_object('ok', true, 'os_created', v_count, 'planning_id', v_planning_id, 'ordens_servico_ids', to_jsonb(v_ids), 'non_lab_items',v_nonlab_count);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_confirmar_entrega_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS'; END IF;
  IF coalesce(btrim(p_recebedor->>'nome'), '') = '' THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_RECEBEDOR_OBRIGATORIO';
  END IF;
  RETURN public.fn_entrega_confirmar_engine_v1(p_entrega_id, p_os_id, p_origem, p_recebedor, '{}'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_estoque_produto_id uuid, p_quantidade numeric, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_est public.estoque_produto%ROWTYPE;
  v_existente record;
  v_id uuid;
  v_cliente_os uuid;
BEGIN
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_os_id IS NULL OR p_estoque_produto_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS';
  END IF;
  IF coalesce(p_quantidade, 0) <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_INVALIDA';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_criar_entrega:' || p_os_id::text || ':' || p_estoque_produto_id::text));

  SELECT * INTO v_est
  FROM public.estoque_produto
  WHERE id = p_estoque_produto_id
  FOR UPDATE;

  IF v_est.id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO';
  END IF;

  IF v_origem = 'onfarm' THEN
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico_onfarm
    WHERE id = p_os_id;
  ELSE
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico
    WHERE id = p_os_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_OS_NAO_ENCONTRADA';
  END IF;

  IF v_est.status::text NOT IN ('reservado', 'expedido') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_STATUS_ESTOQUE_INVALIDO';
  END IF;
  IF v_est.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
  END IF;
  IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
  END IF;
  IF p_quantidade > coalesce(v_est.quantidade, 0) THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
  END IF;
  IF v_est.reservado_para_cliente_id IS NOT NULL
     AND v_est.reservado_para_cliente_id IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;
  IF nullif(p_dados->>'cliente_id','') IS NOT NULL
     AND nullif(p_dados->>'cliente_id','')::uuid IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;

  SELECT e.id, e.status::text AS status INTO v_existente
  FROM public.entregas e
  WHERE e.estoque_produto_id = p_estoque_produto_id
    AND e.status::text <> 'cancelada'
    AND (
      (v_origem = 'onfarm' AND e.ordem_servico_onfarm_id = p_os_id)
      OR (v_origem <> 'onfarm' AND e.ordem_servico_id = p_os_id)
    )
  ORDER BY e.created_at DESC
  LIMIT 1;

  IF v_existente.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_existente.id, 'status', v_existente.status, 'message', 'Entrega ja registrada para este item da OS.');
  END IF;


  IF coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista') NOT IN ('motorista','retirada') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_MODALIDADE_INVALIDA';
  END IF;
  IF coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro') NOT IN ('cadastro','personalizado') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ENDERECO_ORIGEM_INVALIDA';
  END IF;
  IF v_est.volume_total IS NULL OR v_est.volume_total <= 0 OR v_est.volume_total::text IN ('NaN','Infinity','-Infinity')
     OR v_est.quantidade IS NULL OR v_est.quantidade <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_VOLUME_ESTOQUE_INVALIDO';
  END IF;

  INSERT INTO public.entregas (
    ordem_servico_id, ordem_servico_onfarm_id, estoque_produto_id,
    lote_id, produto_id, quantidade_entregue, status, cliente_id,
    data_saida, motorista, veiculo
  ) VALUES (
    CASE WHEN v_origem = 'onfarm' THEN NULL ELSE p_os_id END,
    CASE WHEN v_origem = 'onfarm' THEN p_os_id ELSE NULL END,
    p_estoque_produto_id,
    v_est.lote_id,
    v_est.produto_id,
    p_quantidade,
    'separado'::public.status_entrega,
    v_cliente_os,
    nullif(p_dados->>'data_saida','')::date,
    nullif(p_dados->>'motorista',''),
    nullif(p_dados->>'veiculo','')
  ) RETURNING id INTO v_id;


  -- Only newly created delivery: preserve replay semantics and never overwrite existing history.
  UPDATE public.entregas SET
    volume_entregue_ml = round((v_est.volume_total / v_est.quantidade) * p_quantidade * 1000, 6),
    tipo_entrega = coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista'),
    endereco_origem = coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro'),
    grupo_entrega_id = nullif(p_dados->>'grupo_entrega_id','')::uuid,
    hora_saida_prevista = nullif(p_dados->>'hora_saida_prevista','')::time,
    data_chegada_prevista = nullif(p_dados->>'data_chegada_prevista','')::date,
    hora_chegada_prevista = nullif(p_dados->>'hora_chegada_prevista','')::time,
    motorista_telefone = nullif(p_dados->>'motorista_telefone',''),
    motorista_documento = nullif(p_dados->>'motorista_documento',''),
    veiculo_placa = nullif(p_dados->>'veiculo_placa',''),
    veiculo_tipo = nullif(p_dados->>'veiculo_tipo',''),
    destinatario_nome = nullif(p_dados->>'destinatario_nome',''),
    destinatario_telefone = nullif(p_dados->>'destinatario_telefone',''),
    destinatario_whatsapp = nullif(p_dados->>'destinatario_whatsapp',''),
    endereco_logradouro = nullif(p_dados->>'endereco_logradouro',''),
    endereco_numero = nullif(p_dados->>'endereco_numero',''),
    endereco_complemento = nullif(p_dados->>'endereco_complemento',''),
    endereco_bairro = nullif(p_dados->>'endereco_bairro',''),
    endereco_cidade = nullif(p_dados->>'endereco_cidade',''),
    endereco_uf = nullif(p_dados->>'endereco_uf',''),
    endereco_cep = nullif(p_dados->>'endereco_cep',''),
    endereco_referencia = nullif(p_dados->>'endereco_referencia','')
  WHERE id = v_id;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, etapa_nova, acao, usuario_id, observacao)
  VALUES
    (p_os_id, v_origem, 'entrega_criada', 'criar_entrega_v1', v_uid,
     format('Entrega %s criada (motor transacional).', v_id));

  RETURN jsonb_build_object('success', true, 'replay', false, 'entrega_id', v_id, 'status', 'separado', 'message', 'Entrega registrada. Confirme a entrega para concluir a OS.');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_generate_receivable_from_entrega(_entrega_id uuid, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_receivable_id uuid;
  v_total numeric(14,2);
  v_canon jsonb;
  v_canon_valor numeric;
  v_canon_origem text;
  v_manual boolean;
  v_manual_reason text;
  v_count integer;
  v_category uuid; v_cost_center uuid; v_payment_method uuid;
  v_first_due date; v_issue date;
  v_fiscal_required boolean; v_fiscal_status text;
  v_installments jsonb; v_sum numeric(14,2) := 0; v_inst jsonb;
  v_desc text; v_notes text; v_guard jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para faturar entregas.' USING ERRCODE='insufficient_privilege';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_faturar:' || _entrega_id::text, 0));

  SELECT * INTO v_entrega FROM public.entregas WHERE id = _entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.'; END IF;

  -- H6-003.5 replay estavel
  IF v_entrega.receivable_id IS NOT NULL THEN
    RETURN v_entrega.receivable_id;
  END IF;

  IF v_entrega.status = 'cancelada' THEN
    RAISE EXCEPTION 'Entrega cancelada não pode ser faturada.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.status <> 'entregue' THEN
    RAISE EXCEPTION 'Entrega precisa estar com status "entregue" para faturar.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.cliente_id IS NULL THEN
    RAISE EXCEPTION 'Entrega sem cliente vinculado.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.financial_status = 'NOT_BILLABLE' THEN
    RAISE EXCEPTION 'Entrega marcada como não faturável.' USING ERRCODE='check_violation';
  END IF;

  v_total           := COALESCE((_payload->>'total_amount')::numeric, 0);
  v_count           := COALESCE((_payload->>'installment_count')::integer, 1);
  v_category        := NULLIF(_payload->>'category_id','')::uuid;
  v_cost_center     := NULLIF(_payload->>'cost_center_id','')::uuid;
  v_payment_method  := NULLIF(_payload->>'payment_method_id','')::uuid;
  v_first_due       := COALESCE((_payload->>'first_due_date')::date, CURRENT_DATE);
  v_issue           := COALESCE((_payload->>'issue_date')::date, CURRENT_DATE);
  v_fiscal_required := COALESCE((_payload->>'fiscal_invoice_required')::boolean, false);
  v_fiscal_status   := CASE WHEN v_fiscal_required THEN 'PENDING' ELSE 'NOT_REQUIRED' END;
  v_installments    := _payload->'installments';
  v_desc            := COALESCE(NULLIF(_payload->>'description',''), 'Entrega ' || substr(_entrega_id::text,1,8));
  v_notes           := NULLIF(_payload->>'notes','');
  v_manual          := COALESCE((_payload->>'manual_financial_adjustment')::boolean, false);
  v_manual_reason   := NULLIF(trim(_payload->>'manual_adjustment_reason'), '');

  IF v_category IS NULL THEN
    RAISE EXCEPTION 'Categoria financeira é obrigatória.' USING ERRCODE='check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.financial_categories WHERE id = v_category) THEN
    RAISE EXCEPTION 'Categoria financeira não encontrada.' USING ERRCODE='check_violation';
  END IF;
  IF v_count < 1 OR v_count > 36 THEN
    RAISE EXCEPTION 'Número de parcelas deve estar entre 1 e 36.' USING ERRCODE='check_violation';
  END IF;

  -- ------- H6-003: valor canonico server-side é a autoridade do total -------
  v_canon := public.fn_entrega_valor_faturavel_v1(_entrega_id);
  v_canon_origem := v_canon->>'origem';

  -- reconciliacao parcial: usa exatamente o valor_faturavel_max persistido
  SELECT r.valor_faturavel_max INTO v_canon_valor
    FROM public.entrega_reconciliacoes r
   WHERE r.entrega_id = _entrega_id AND r.status = 'reconciliada'
   LIMIT 1;
  IF v_canon_valor IS NULL THEN
    v_canon_valor := (v_canon->>'valor')::numeric;
  ELSE
    v_canon_origem := 'RECONCILIACAO:' || COALESCE(v_canon_origem,'-');
  END IF;

  IF v_canon_valor IS NOT NULL THEN
    IF abs(v_total - v_canon_valor) > 0.01 THEN
      RAISE EXCEPTION 'valor_divergente_do_canonico: informado %, canônico % (origem %).',
        v_total, v_canon_valor, v_canon_origem USING ERRCODE='check_violation';
    END IF;
    v_total := round(v_canon_valor, 2);
  ELSE
    -- sem fonte historica confiavel: exige ajuste financeiro manual justificado
    IF NOT v_manual OR v_manual_reason IS NULL OR length(v_manual_reason) < 10 THEN
      RAISE EXCEPTION 'valor_canonico_indisponivel: informe manual_financial_adjustment com motivo (mín. 10 caracteres).'
        USING ERRCODE='check_violation';
    END IF;
  END IF;

  IF v_total <= 0 THEN
    RAISE EXCEPTION 'Valor total inválido.' USING ERRCODE='check_violation';
  END IF;

  -- GATE: reconciliação obrigatória quando há conferência por item
  v_guard := public.fn_entrega_guard_faturamento_v1(_entrega_id, v_total);

  IF v_installments IS NOT NULL AND jsonb_array_length(v_installments) > 0 THEN
    IF jsonb_array_length(v_installments) <> v_count THEN
      RAISE EXCEPTION 'Quantidade de parcelas (%) diverge de installment_count (%).',
        jsonb_array_length(v_installments), v_count USING ERRCODE='check_violation';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      v_sum := v_sum + COALESCE((v_inst->>'amount')::numeric, 0);
    END LOOP;
    IF abs(v_sum - v_total) > 0.01 THEN
      RAISE EXCEPTION 'Soma das parcelas (%) difere do total (%).', v_sum, v_total USING ERRCODE='check_violation';
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.accounts_receivable (
      origin_type, origin_id, customer_id, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count,
      payment_method_id, fiscal_invoice_required, fiscal_invoice_status,
      notes, created_by
    ) VALUES (
      'DELIVERY', _entrega_id, v_entrega.cliente_id, v_desc, v_category, v_cost_center,
      v_total, v_issue, v_first_due, v_count,
      v_payment_method, v_fiscal_required, v_fiscal_status,
      v_notes, v_uid
    ) RETURNING id INTO v_receivable_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_receivable_id FROM public.accounts_receivable
     WHERE origin_type = 'DELIVERY' AND origin_id = _entrega_id AND status <> 'CANCELED';
    IF v_receivable_id IS NOT NULL THEN RETURN v_receivable_id; END IF;
    RAISE EXCEPTION 'Entrega já possui conta a receber ativa.' USING ERRCODE='check_violation';
  END;

  IF v_installments IS NOT NULL AND jsonb_array_length(v_installments) > 0 THEN
    DELETE FROM public.accounts_receivable_installments WHERE receivable_id = v_receivable_id;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      INSERT INTO public.accounts_receivable_installments (
        receivable_id, installment_number, due_date, original_amount, net_amount, status
      ) VALUES (
        v_receivable_id,
        (v_inst->>'installment_number')::integer,
        (v_inst->>'due_date')::date,
        (v_inst->>'amount')::numeric,
        (v_inst->>'amount')::numeric,
        'OPEN'
      );
    END LOOP;
  END IF;

  UPDATE public.entregas
     SET receivable_id = v_receivable_id,
         financial_status = 'BILLED',
         billing_generated_at = now(),
         billing_generated_by = v_uid
   WHERE id = _entrega_id;

  INSERT INTO public.financial_audit_log (
    entity_type, entity_id, action, old_data, new_data, performed_by
  ) VALUES (
    'entregas', _entrega_id, 'DELIVERY_BILLED',
    jsonb_build_object('receivable_id', v_entrega.receivable_id,
                       'financial_status', v_entrega.financial_status),
    jsonb_build_object('receivable_id', v_receivable_id, 'total_amount', v_total,
      'installment_count', v_count, 'fiscal_invoice_required', v_fiscal_required,
      'payment_method_id', v_payment_method, 'origem', 'entrega',
      'valor_canonico', v_canon_valor, 'valor_canonico_origem', v_canon_origem,
      'manual_financial_adjustment', v_manual, 'manual_adjustment_reason', v_manual_reason,
      'reconciliacao', v_guard),
    v_uid
  );

  RETURN v_receivable_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_programar_os_v1(p_os_id uuid, p_origem text, p_data_programada date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid:=auth.uid(); v_org uuid; v_origin text; v_os record;
 v_pp public.programacao_producao%ROWTYPE; v_before jsonb; v_after jsonb;
 v_count integer; v_canonical text; v_status text;
BEGIN
 -- Local wait bound also applies to normal SDK calls, not only migration transaction.
 PERFORM pg_catalog.set_config('lock_timeout','3s',true);
 -- O helper corrente valida a cadeia completa atual, não a MV; antes de status/replay.
 v_org:=platform_private.h15_actor_organization();
 IF v_uid IS NULL OR v_org IS NULL OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE THEN
 RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin <> 'manual' THEN RETURN jsonb_build_object('success',false,'message','Somente OS manual neste recorte.'); END IF;
 v_canonical:='manual';
 IF p_os_id IS NULL OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=v_canonical) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Authoritative phantom fences: conservative table locks, bounded by review transaction.
 -- Never use this path from REPEATABLE READ: stale snapshots cannot reauthorize.
 IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'PROGRAMAR_ISOLATION_DENIED' USING ERRCODE='42501'; END IF;
 -- Immediate FK checks take KEY SHARE on the locked OS/program parent.
 -- No table locks on production links or lots; parent UPDATE prevents new target references.
 -- Invites have NO user/profile FK: retain bounded SHARE against insert phantoms.
 LOCK TABLE public.platform_org_admin_invites,public.ordens_servico_onfarm IN SHARE MODE;
 -- Onfarm IDs have no FK to manual OS: retain phantom fence against a duplicate ID.
 -- Global published catalog still requires phantom protection; never drop SaaS gate.
 LOCK TABLE public.saas_plan_versions,public.saas_plan_version_features,public.saas_features,public.saas_modules IN SHARE MODE;
 SELECT o.organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,o.status::text status,o.volume_total_ml,o.data_programada os_date,o.partner_order_id,o.partner_order_item_id,o.origem INTO v_os FROM public.ordens_servico o WHERE o.id=p_os_id FOR UPDATE;
 IF v_os.id IS NULL OR (v_canonical='manual' AND v_os.organization_id IS DISTINCT FROM v_org) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Locks sobre referências atuais. Revalidação posterior impede respostas antigas.
 PERFORM 1 FROM public.profiles WHERE user_id=v_uid OR id IN (SELECT responsavel_id FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id) ORDER BY user_id FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=v_uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
 -- Org FK plus parent UPDATE fences new subscriptions/overrides for this tenant.
 PERFORM 1 FROM public.organization_subscriptions WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.organization_feature_overrides WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=v_os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=v_os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=v_os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=v_os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 IF public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=v_canonical) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- B2B/links acionam sync comercial/planejamento/notificações não homologados.
 IF v_origin='b2b' OR v_os.origem='b2b' OR v_os.partner_order_id IS NOT NULL OR v_os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','Programação B2B indisponível até validação dos efeitos associados.'); END IF;
 SELECT count(*) INTO v_count FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF v_count<>1 THEN RETURN jsonb_build_object('success',false,'message','Programação existente não comprovada; revisão necessária.'); END IF;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF NOT ((v_pp.organization_id=v_org AND ((v_canonical='manual' AND v_pp.ordem_servico_id=p_os_id AND v_pp.ordem_servico_onfarm_id IS NULL) OR (v_canonical='onfarm' AND v_pp.ordem_servico_onfarm_id=p_os_id AND v_pp.ordem_servico_id IS NULL)) AND v_pp.produto_id IS NOT DISTINCT FROM v_os.produto_id AND v_pp.microrganismo_id IS NOT DISTINCT FROM v_os.microrganismo_id) IS TRUE) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- FK responsável usa profiles.id; helper legado usa user_id. Não reinterpretar silenciosamente.
 IF v_pp.responsavel_id IS NOT NULL OR nullif(btrim(v_pp.responsavel),'') IS NOT NULL THEN RETURN jsonb_build_object('success',false,'message','Responsável não nulo indisponível neste recorte.'); END IF;
 IF v_os.status IS NULL OR v_os.status NOT IN ('aprovada','programada') THEN RETURN jsonb_build_object('success',false,'message','A OS deve estar previamente aprovada; esta ação não aprova nem inicia fabricação.'); END IF;
 IF platform_private.lab_item_is_manufacturable(v_os.produto_id,v_os.microrganismo_id) IS NOT TRUE THEN RETURN jsonb_build_object('success',false,'message','Item não elegível ao laboratório biológico.'); END IF;
 IF EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id) OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE ordem_servico_id=p_os_id) THEN RETURN jsonb_build_object('success',false,'message','OS com entrega/aplicação já vinculada indisponível neste recorte.'); END IF;
 IF v_pp.status::text IS DISTINCT FROM 'aguardando' OR EXISTS(SELECT 1 FROM public.lotes WHERE programacao_id=v_pp.id) THEN RETURN jsonb_build_object('success',false,'message','A programação já avançou; operação indisponível.'); END IF;
 IF p_data_programada IS NULL OR NOT isfinite(p_data_programada) THEN RETURN jsonb_build_object('success',false,'message','Informe uma data válida, sem inferência automática.'); END IF;
 v_before:=jsonb_build_object('status_os',v_os.status,'data_os',v_os.os_date,'data_programacao',v_pp.data_programada,'status_programacao',v_pp.status,'volume_os',v_os.volume_total_ml,'volume_programacao',v_pp.volume_necessario);
 IF v_os.status='programada' AND v_pp.data_programada IS NOT DISTINCT FROM p_data_programada AND (v_canonical='onfarm' OR v_os.os_date IS NOT DISTINCT FROM p_data_programada) THEN RETURN jsonb_build_object('success',true,'replay',true,'status','programada','message','Programação já corresponde à data informada.'); END IF;
 -- Three-argument contract: only first scheduling and identical-state replay.
 -- Different date on a programmed OS is denied, preventing delayed A/B/A retries.
 IF v_os.status='programada' THEN RETURN jsonb_build_object('success',false,'message','OS já programada. Alteração de data indisponível neste contrato.'); END IF;
 -- Sem INSERT de programação/lote: usa somente programação previamente criada pelo fluxo.
 UPDATE public.ordens_servico SET status='programada',data_programada=p_data_programada WHERE id=p_os_id;
 -- Existing downstream trigger sets the same program date; avoid a second global refresh.
 -- No explicit program UPDATE/INSERT: exact downstream postcondition below is authoritative.
 SELECT * INTO v_pp FROM public.programacao_producao WHERE id=v_pp.id;
 IF v_pp.responsavel_id IS NOT NULL OR v_pp.organization_id IS DISTINCT FROM v_org OR v_pp.status::text IS DISTINCT FROM 'aguardando' OR v_pp.data_programada IS DISTINCT FROM p_data_programada OR EXISTS(SELECT 1 FROM public.lotes WHERE programacao_id=v_pp.id)
 OR public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=v_canonical) THEN RAISE EXCEPTION 'PROGRAMAR_POSTCONDITION_FAILED'; END IF;
 v_after:=jsonb_build_object('status_os','programada','data_os',CASE WHEN v_canonical='manual' THEN p_data_programada ELSE NULL END,'data_programacao',v_pp.data_programada,'status_programacao',v_pp.status,'volume_os',v_os.volume_total_ml,'volume_programacao',v_pp.volume_necessario);
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 VALUES(p_os_id,v_canonical,v_pp.id,v_os.status,'programada','programar_os',v_uid,jsonb_build_object('organization_id',v_org,'before',v_before,'after',v_after,'actor',v_uid,'at',clock_timestamp(),'manufacturing_started',false)::text);
 -- Refresh interno existente por trigger permanece; nenhum refresh adicional/client-side.
 RETURN jsonb_build_object('success',true,'replay',false,'status','programada','message','Data programada; fabricação não iniciada.');
END $function$
